def _validate_request(data, request_id):
    """Validate and normalize the inputs for an API request.

    Returns the normalized request ID so callers do not need to repeat the
    whitespace handling performed during validation.
    """
    if not isinstance(data, dict):
        raise TypeError("data must be a dictionary")

    if not isinstance(request_id, str):
        raise TypeError("request_id must be a string")

    normalized_request_id = request_id.strip()
    if not normalized_request_id:
        raise ValueError("request_id must not be empty")

    return normalized_request_id


def handle_request(data, request_id):
    """Validate, audit, and process an incoming API request."""
    request_id = _validate_request(data, request_id)
    audit_log(request_id, data)
    return process(data)

